"""Render manuscript macros, tables, and figure for revision experiments."""
from __future__ import annotations

import json
import os
from pathlib import Path

os.environ.setdefault("MPLCONFIGDIR", "/private/tmp/cfa-matplotlib")
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

HERE = Path(__file__).resolve().parent
PAPER = HERE.parent
OUTPUT = HERE / "outputs"


def pct(value): return f"{100 * value:.1f}"


def write_macros(path, values):
    path.write_text(
        "% Generated by repro/render_revision_outputs.py\n"
        + "\n".join("\\newcommand{\\" + key + "}{" + value + "}" for key, value in values.items())
        + "\n"
    )


def main():
    controls = json.loads((OUTPUT / "intervention_controls_analysis.json").read_text())
    efficiency = json.loads((OUTPUT / "efficiency_sweep_analysis.json").read_text())
    semantic = json.loads((OUTPUT / "semantic_label_validation.json").read_text())
    allv, correct = controls["overall"], controls["datasets"]["full_answer_correct"]
    c = lambda block, key: block[key]
    values = {
        "ctrlN": str(controls["n"]), "ctrlAgree": pct(c(allv, "delete_mask_label_agreement")["mean"]),
        "ctrlAgreeLo": pct(c(allv, "delete_mask_label_agreement")["ci95"][0]),
        "ctrlAgreeHi": pct(c(allv, "delete_mask_label_agreement")["ci95"][1]),
        "ctrlConfirm": pct(c(allv, "delete_positive_confirmed_by_mask")["mean"]),
        "ctrlConfirmLo": pct(c(allv, "delete_positive_confirmed_by_mask")["ci95"][0]),
        "ctrlConfirmHi": pct(c(allv, "delete_positive_confirmed_by_mask")["ci95"][1]),
        "ctrlCorrectN": str(correct["n_questions"]),
        "ctrlCorrectAgree": pct(c(correct, "delete_mask_label_agreement")["mean"]),
        "ctrlCorrectAgreeLo": pct(c(correct, "delete_mask_label_agreement")["ci95"][0]),
        "ctrlCorrectAgreeHi": pct(c(correct, "delete_mask_label_agreement")["ci95"][1]),
        "ctrlCorrectConfirm": pct(c(correct, "delete_positive_confirmed_by_mask")["mean"]),
        "ctrlCorrectConfirmLo": pct(c(correct, "delete_positive_confirmed_by_mask")["ci95"][0]),
        "ctrlCorrectConfirmHi": pct(c(correct, "delete_positive_confirmed_by_mask")["ci95"][1]),
        "ctrlCorrectSet": pct(c(correct, "exact_sensitive_set_match")["mean"]),
        "ctrlCorrectJoint": pct(c(correct, "joint_gold_mask_change_rate")["mean"]),
        "ctrlCorrectJointLo": pct(c(correct, "joint_gold_mask_change_rate")["ci95"][0]),
        "ctrlCorrectJointHi": pct(c(correct, "joint_gold_mask_change_rate")["ci95"][1]),
        "ctrlCorrectJointOnly": pct(c(correct, "joint_only_beyond_single_gold_mask")["mean"]),
        "ctrlCorrectJointOnlyLo": pct(c(correct, "joint_only_beyond_single_gold_mask")["ci95"][0]),
        "ctrlCorrectJointOnlyHi": pct(c(correct, "joint_only_beyond_single_gold_mask")["ci95"][1]),
        "semPairs": str(semantic["n_answer_pairs"]),
        "semPrecision": pct(semantic["thresholds"]["0.85"]["string_change_precision_for_semantic_change"]),
        "semAgreement": pct(semantic["thresholds"]["0.85"]["delete_mask_semantic_label_agreement"]),
    }
    methods = {"oof": "OOF CFA", "dense": "Dense", "cross_encoder": "Cross-encoder",
               "ce_rank_length": "CE rank + length", "contextcite": "ContextCite"}
    for method in methods:
        v = efficiency["overall"][f"{method}_tok768"]
        prefix = {"oof": "tokOOF", "dense": "tokDense", "cross_encoder": "tokCE",
                  "ce_rank_length": "tokCELength", "contextcite": "tokCC"}[method]
        values.update({prefix + "Cover": pct(v["cover"]), prefix + "Fone": pct(v["f1"]),
                       prefix + "Tokens": f"{v['context_tokens']:.0f}", prefix + "GR": pct(v["gold_recall"])})
    contrast = {(x["left"], x["right"], x["metric"]): x for x in efficiency["contrasts"]}
    cc = contrast[("oof_tok768", "contextcite_tok768", "cover")]
    ce = contrast[("oof_tok768", "cross_encoder_tok768", "cover")]
    values.update({
        "tokDeltaCC": f"{100 * cc['difference']:+.1f}", "tokDeltaCCLo": f"{100 * cc['ci95'][0]:+.1f}",
        "tokDeltaCCHi": f"{100 * cc['ci95'][1]:+.1f}", "tokDeltaCE": f"{100 * ce['difference']:+.1f}",
        "tokDeltaCELo": f"{100 * ce['ci95'][0]:+.1f}", "tokDeltaCEHi": f"{100 * ce['ci95'][1]:+.1f}",
    })
    calibrated = efficiency["overall"]["oof_calibrated"]
    fixed = efficiency["overall"]["oof_threshold_0.5"]
    t02 = efficiency["overall"]["oof_threshold_0.2"]
    values.update({"calCover": pct(calibrated["cover"]), "calTokens": f"{calibrated['context_tokens']:.0f}",
                   "calRet": f"{calibrated['n_selected']:.2f}", "fixedCoverStable": pct(fixed["cover"]),
                   "fixedTokensStable": f"{fixed['context_tokens']:.0f}", "thrTwoCover": pct(t02["cover"]),
                   "thrTwoTokens": f"{t02['context_tokens']:.0f}"})
    write_macros(PAPER / "controlmacros.tex", values)

    rows = []
    for label, block in [("All questions", allv), ("Full answer correct", correct)]:
        rows.append(
            f"{label} & {block['n_questions']} & {pct(c(block, 'delete_mask_label_agreement')['mean'])} & "
            f"{pct(c(block, 'delete_positive_confirmed_by_mask')['mean'])} & "
            f"{pct(c(block, 'exact_sensitive_set_match')['mean'])} & "
            f"{pct(c(block, 'joint_gold_mask_change_rate')['mean'])} & "
            f"{pct(c(block, 'joint_only_beyond_single_gold_mask')['mean'])} \\\\"
        )
    (PAPER / "tab_intervention_controls.tex").write_text(
        "\\begin{tabular}{lrrrrrr}\n\\toprule\nPopulation & $n$ & Agr. & Conf. & Set & Joint & J-only \\\\\n"
        "\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n"
    )

    order = ["oof", "dense", "cross_encoder", "ce_rank_length", "contextcite"]
    table = ["\\begin{tabular}{lrrrrrr}", "\\toprule",
             "Method & Ret. & Cover & $F_1$ & Tok. & GR & Probes \\\\ ", "\\midrule"]
    for method in order:
        v = efficiency["overall"][f"{method}_tok768"]
        label = "\\textbf{OOF CFA selector}" if method == "oof" else methods[method]
        cover = f"{100*v['cover']:.1f}"
        gr = f"{100*v['gold_recall']:.1f}"
        if method == "contextcite": cover = f"\\textbf{{{cover}}}"
        if method == "oof": gr = f"\\textbf{{{gr}}}"
        table.append(f"{label} & {v['n_selected']:.2f} & {cover} & {100*v['f1']:.1f} & "
                     f"{v['context_tokens']:.0f} & {gr} & {v['probe_calls']:.0f} \\\\ ")
    table += ["\\bottomrule", "\\end{tabular}"]
    (PAPER / "tab_token_budget.tex").write_text("\n".join(table) + "\n")

    colors = {"oof": "#1967d2", "dense": "#777777", "cross_encoder": "#e07a1f",
              "ce_rank_length": "#2a9d8f", "contextcite": "#7b2cbf"}
    markers = {"oof": "o", "dense": "s", "cross_encoder": "^", "ce_rank_length": "D", "contextcite": "P"}
    fig, axes = plt.subplots(1, 2, figsize=(7.1, 2.55))
    for method in order:
        xs, ys = [], []
        for budget in [256, 512, 768]:
            v = efficiency["overall"][f"{method}_tok{budget}"]
            xs.append(v["context_tokens"]); ys.append(100 * v["cover"])
        width = 2.2 if method == "oof" else 1.35
        short_label = {"oof": "OOF", "dense": "Dense", "cross_encoder": "Cross-enc.",
                       "ce_rank_length": "CE+len.", "contextcite": "ContextCite"}[method]
        axes[0].plot(xs, ys, marker=markers[method], color=colors[method], linewidth=width,
                     markersize=4.5, label=short_label)
    axes[0].set(xlabel="Mean context tokens", ylabel="Cover-EM (\%)", title="(a) Equal-token budgets")
    axes[0].grid(alpha=.22)
    points = []
    for threshold in [0.5, 0.4, 0.3, 0.2, 0.1]:
        v = efficiency["overall"][f"oof_threshold_{threshold:.1f}"]
        points.append((v["context_tokens"], 100*v["cover"], threshold))
    axes[1].plot([p[0] for p in points], [p[1] for p in points], "o-", color=colors["oof"], linewidth=2)
    for x, y, threshold in points:
        axes[1].annotate(f"{threshold:.1f}", (x, y), xytext=(3, 3), textcoords="offset points", fontsize=6.2)
    axes[1].scatter([calibrated["context_tokens"]], [100*calibrated["cover"]], marker="*", s=85,
                    color="#c62828", zorder=5)
    axes[1].set(xlabel="Mean context tokens", ylabel="Cover-EM (\%)", title="(b) OOF threshold curve")
    axes[1].grid(alpha=.22)
    axes[1].annotate("CV", (calibrated["context_tokens"], 100*calibrated["cover"]),
                     xytext=(5, -8), textcoords="offset points", fontsize=6.2, color="#9f1d1d")
    for ax in axes:
        ax.title.set_fontsize(8.5)
        ax.xaxis.label.set_size(7.8); ax.yaxis.label.set_size(7.8)
        ax.tick_params(labelsize=7)
    handles, labels = axes[0].get_legend_handles_labels()
    fig.legend(handles, labels, loc="lower center", bbox_to_anchor=(0.5, 0.005),
               ncol=5, fontsize=6.2, frameon=False, handlelength=1.7,
               columnspacing=1.25, handletextpad=0.4)
    fig.tight_layout(w_pad=1.4, rect=(0, 0.09, 1, 1))
    fig.savefig(PAPER / "images" / "revision_controls.pdf", bbox_inches="tight")
    fig.savefig(PAPER / "images" / "revision_controls.png", dpi=220, bbox_inches="tight")
    plt.close(fig)

    metric_defs = [
        ("delete_mask_label_agreement", "Delete/mask label agreement"),
        ("delete_positive_confirmed_by_mask", "Deletion positives confirmed"),
        ("exact_sensitive_set_match", "Exact sensitive-set match"),
        ("joint_gold_mask_change_rate", "Joint support-set change"),
        ("joint_only_beyond_single_gold_mask", "Joint-only effect"),
    ]
    fig, ax = plt.subplots(figsize=(3.55, 2.7))
    y = list(range(len(metric_defs)))[::-1]
    for offset, block, label, color, marker in [
        (0.10, allv, "All questions", "#6b7280", "s"),
        (-0.10, correct, "Full answer correct", "#1967d2", "o"),
    ]:
        means = [100 * block[key]["mean"] for key, _ in metric_defs]
        low = [100 * (block[key]["mean"] - block[key]["ci95"][0]) for key, _ in metric_defs]
        high = [100 * (block[key]["ci95"][1] - block[key]["mean"]) for key, _ in metric_defs]
        ax.errorbar(means, [v + offset for v in y], xerr=[low, high], fmt=marker,
                    color=color, ecolor=color, elinewidth=1.2, capsize=2.5,
                    markersize=5, label=label)
    ax.set_yticks(y, [label for _, label in metric_defs], fontsize=7.2)
    ax.set(xlim=(-2, 102), xlabel="Rate (%)")
    ax.grid(axis="x", alpha=.22)
    ax.legend(fontsize=6.6, frameon=False, loc="lower right")
    fig.tight_layout()
    fig.savefig(PAPER / "images" / "intervention_controls.pdf", bbox_inches="tight")
    fig.savefig(PAPER / "images" / "intervention_controls.png", dpi=220, bbox_inches="tight")
    plt.close(fig)


if __name__ == "__main__":
    main()
